"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "@/lib/utils"

const Slider = React.forwardRef<HTMLDivElement, SliderPrimitive.Root.Props>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max]

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full", className)}
        {...props}
      >
        <SliderPrimitive.Control className="flex w-full touch-none select-none items-center">
          <SliderPrimitive.Track
            data-slot="slider-track"
            className={cn(
              "relative h-3 w-full grow overflow-hidden rounded-[0.125rem] border-2 border-border",
              "bg-card [box-shadow:var(--shadow-xs)]"
            )}
          >
            <SliderPrimitive.Indicator data-slot="slider-range" className="absolute h-full bg-primary" />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb
              data-slot="slider-thumb" key={index}
              className={cn(
                "block h-5 w-5 rounded-[0.125rem] border-2 border-border bg-primary",
                "[box-shadow:var(--shadow-primary)]",
                "transition-[box-shadow,transform] duration-fast",
                "hover:-translate-x-px hover:-translate-y-px hover:[box-shadow:var(--shadow-button-hover)]",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                "data-disabled:pointer-events-none data-disabled:opacity-50"
              )}
            />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    )
  }
)
Slider.displayName = "Slider"

export { Slider }
